import env from "xabber-environment";

let constants = env.constants,
    _ = env._,
    $ = env.$,
    moment = env.moment,
    client_translation_progress = env.client_translation_progress,
    xabber_i18next = env.xabber_i18next,
    xabber_i18next_sprintf = env.xabber_i18next_sprintf,
    uuid = env.uuid,
    Backbone = env.Backbone,
    utils = env.utils;


let Xabber = Backbone.Model.extend({
    defaults: {
        version_number: env.version_number,
        actual_version_number: env.version_number,
        audio: false,
        video: false,
        client_id: uuid().substring(0, 8),
    },

    initialize: function () {
        this.env = env;
        this.fetchURLParams();
        this.cleanUpStorage();
        this.initDefaultLanguage();
        this.detectMediaDevices();
        window.navigator.mediaDevices && (window.navigator.mediaDevices.ondevicechange = this.detectMediaDevices.bind(this));
        this.check_config = new $.Deferred();
        this._settings = new this.Settings({id: 'settings'},
                {storage_name: this.getStorageName(), fetch: 'before'});
        this.settings = this._settings.attributes;
        let url = window.location.host + window.location.pathname.replace(/\//g, "-");
        if (url[url.length - 1] === "-")
            url.slice(0, url.length - 1);
        this._cache = new Backbone.ModelWithStorage({id: `cache-${url}`},
                {storage_name: this.getStorageName(), fetch: 'before'});
        this._avatar_urls_cache = new Backbone.ModelWithStorage({id: `cache-avatar-urls-${url}`},
                {storage_name: this.getStorageName(), fetch: 'before'});
        this.cache = this._cache.attributes;
        this.cache.client_id && (this.set('client_id', this.cache.client_id));
        this._avatar_urls_cache.save('version_time', new Date());
        this._cache.save('client_id', this.get('client_id'));
        this.extendFunction();
        this.plyr_players = [];
        this.current_plyr_player = null;
        this.on("change:actual_version_number", this.throwNewVersion, this);
        this.on("quit", this.onQuit, this);
        this._version_interval = setInterval(this.readActualVersion.bind(this), 600000);

        window.onerror = (msg, url, line, col, error) => {
            utils.dialogs.error(msg + '\n' + url + '\n' + line + ':' + col + '\n' + error);
        };
        window.ononline = () => {
            this.disconnectWhenConnecting();
        };
    },

    initDefaultLanguage: function () {
        let lang = window.navigator.language,
            progress = Object.keys(client_translation_progress).find(key => !lang.indexOf(key)) || constants.languages_another_locales[lang] && Object.keys(client_translation_progress).find(key => !constants.languages_another_locales[lang].indexOf(key));
        if (progress !== 100)
            lang = 'en';
        this.set("default_language", lang);
    },

    loadTranslations: async function (lang) {
        return new Promise((resolve, reject) => {
            let language = {};
            language.lang = lang;
            !language.lang && (language.lang = this.settings.language);
            if (language.lang === 'default' && this.default_translation) {
                language.lang = this.get("default_language");
                language.translation  = this.default_translation;
                resolve(language);
                return;
            }
            import(`~/translations/${language.lang.replace(/-/g, "-r")}.js`).then(translation => {
                language.translation  = translation;
                resolve(language)
            });
        });
    },

    setLocale: function (lang, translations) {
        let default_lang = this.get("default_language"),
            _translations = {
                [default_lang]: {
                    translation: this.default_translation
                }
            };
        lang && (_translations[lang] = {translation: translations});
        xabber_i18next.use(xabber_i18next_sprintf);
        xabber_i18next.init({
            lng: default_lang,
            debug: false,
            pluralSeparator: '-',
            resources: _translations
        });
        if (lang) {
            xabber_i18next.changeLanguage(lang);
            moment.locale(lang);
        }
        xabber_i18next.default_lang = xabber_i18next.getFixedT(default_lang);
    },
    getOneLiners: function () {
        if (xabber_i18next.exists("motivating_oneliner")) {
            return xabber_i18next.t("motivating_oneliner").replace(/\\'/g, "'").split('\n');
        } else if (xabber_i18next.default_lang) {
            return xabber_i18next.default_lang("motivating_oneliner").replace(/\\'/g, "'").split('\n');
        } else
            return [];
    },
    getString: function (id, params) {
        if (xabber_i18next.exists(id)) {
            return xabber_i18next.t(id, { postProcess: 'sprintf', sprintf: params}).replace(/\\'/g, "'").replace(/%+\d+[$]/g, "%").replace(/\\n/g, '&#10;');
        } else if (xabber_i18next.default_lang) {
            return xabber_i18next.default_lang(id, { postProcess: 'sprintf', sprintf: params}).replace(/\\'/g, "'").replace(/%+\d+[$]/g, "%").replace(/\\n/g, '&#10;');
        } else
            return "";
    },

    getQuantityString: function (id, count, params) {
        let lang = xabber_i18next.language,
            plurals = xabber_i18next.services.pluralResolver.getRule(lang);
        if (!plurals)
            return this.getString(`${id}_plural_0`, (params || [count]));
        let _count = parseInt(count, 10);
        xabber_i18next.services.pluralResolver.options.compatibilityJSON = 'v0';
        let suffix = xabber_i18next.services.pluralResolver.getSuffix(lang, _count);
        suffix = suffix.replace(/-/g, "_");
        if (xabber_i18next.language === 'en' || !xabber_i18next.exists(`${id}_plural${suffix}`)) {
            suffix = xabber_i18next.services.pluralResolver.getSuffix("en", _count);
            if (!suffix || suffix && !suffix.length)
                suffix = '_0';
            else
                suffix = '_1';
        }
        return this.getString(`${id}_plural${suffix}`, (params || [count]));
    },

    error: function (msg) {
        if (constants.LOG_LEVEL <= constants.LOG_LEVEL_ERROR) {
            console.error(msg);
        }
    },

    warn: function (msg) {
        if (constants.LOG_LEVEL <= constants.LOG_LEVEL_WARN) {
            console.warn(msg);
        }
    },

    info: function (msg) {
        if (constants.LOG_LEVEL <= constants.LOG_LEVEL_INFO) {
            console.log(msg);
        }
    },

    debug: function (msg) {
        if (constants.LOG_LEVEL <= constants.LOG_LEVEL_DEBUG) {
            console.log(msg);
        }
    },

    pretty_last_seen: function (seconds) {
        if (seconds >= 0 && seconds <= 120)
            return this.getString("last_seen_now");
        if (seconds > 120 && seconds < 3600)
            return this.getString("last_seen_minutes", [Math.trunc(seconds/60)]);
        if (seconds >= 3600 && seconds < 7200)
            return this.getString("last_seen_hours");
        if (seconds >= 3600*48*2)
            return this.getString("last_seen_date", [env.moment().subtract(seconds, 'seconds').format('LL')]);
        else
            return this.getString("last_seen_date", [env.moment().subtract(seconds, 'seconds').calendar().toLowerCase()]);
    },

    readActualVersion: function () {
        if (!constants.CHECK_VERSION)
            return;
        // get version.js file from server and parse it
        let rawFile = new XMLHttpRequest();
        rawFile.open("GET", "version.js?"+uuid(), true);
        rawFile.onreadystatechange = () => {
            if (rawFile.readyState === 4 && rawFile.status === 200) {
                let text, json;
                rawFile.onreadystatechange = null;
                try {
                    text = rawFile.responseText;
                    json = JSON.parse(text.split('\n')[1].slice(1, -1));
                } catch (e) {
                    return;
                }
                this.set({
                    actual_version_number: json.version_number,
                    version_description: json.version_description
                });
            }
        };
        rawFile.send();
    },

    extendFunction: function () {
        if (!String.prototype.trimStart) {
            String.prototype.trimStart = function () {
                return this.replace(/^\s+/, '');
            }
        }
        if (!String.prototype.trimEnd) {
            String.prototype.trimEnd = function () {
                return Array.from(Array.from(this).reverse().join("").trimStart(/\s$/, '')).reverse().join("");
            }
        }
    },

    onQuit: function () {
        if (window.indexedDB.databases) {
            window.indexedDB.databases().then((a) => {
                a.forEach((db) => {
                    window.indexedDB.deleteDatabase(db.name)
                });
            });
        } else {
            this.accounts.forEach((acc) => {
                indexedDB.deleteDatabase(acc.cached_roster.database.name);
                indexedDB.deleteDatabase(acc.cached_sync_conversations.database.name);
                indexedDB.deleteDatabase(acc.cached_notifications.database.name);
                indexedDB.deleteDatabase(acc.cached_calls.database.name);
                indexedDB.deleteDatabase(acc.cached_server_features.database.name);
            });
        }
        let full_storage_name = this.getStorageName();
        for (let key in window.localStorage) {
            if (key.startsWith(full_storage_name) || key.startsWith(constants.STORAGE_NAME + '-' + constants.STORAGE_VERSION + '-' + this.cache.id)) {
                window.localStorage.removeItem(key);
            }
        }
    },

    cacheFavicons: async function () {
        this._cache.save('placeholder_loading', URL.createObjectURL(await fetch(constants.LOADING_PLACEHOLDER).then(r => r.blob())));
        this._cache.save('favicon', URL.createObjectURL(await fetch(constants.FAVICON_DEFAULT).then(r => r.blob())));
        this._cache.save('favicon_gray', URL.createObjectURL(await fetch(constants.FAVICON_DEFAULT_GREY).then(r => r.blob())));
        this._cache.save('favicon_message', URL.createObjectURL(await fetch(constants.FAVICON_MESSAGE).then(r => r.blob())));
        this._cache.save('favicon_notification', URL.createObjectURL(await fetch(constants.FAVICON_NOTIFICATION).then(r => r.blob())));
    },

    detectMediaDevices: function () {
        this.getMediaDevices((media_devices) => {
            this.set(media_devices);
        });
    },

    getMediaDevices: function (callback, errback) {
        if (window.navigator && window.navigator.mediaDevices) {
            window.navigator.mediaDevices.enumerateDevices()
                .then((devices) => {
                    let media_devices = {audio: false, video: false};
                    (devices.find(device => device.kind === 'audioinput')) && (media_devices.audio = true);
                    (devices.find(device => device.kind === 'videoinput')) && (media_devices.video = true);
                    callback && callback(media_devices);
                })
                .catch((err) => {
                    errback && errback(err);
                });
        }
    },

    throwNewVersion: function () {
        if (!constants.CHECK_VERSION)
            return;
        let version_number = this.get('actual_version_number'),
            version_description = this.get('version_description');
        utils.dialogs.common(this.getString("dialog_version_update__header", [constants.CLIENT_NAME]), `${this.getString("dialog_version_update__confirm_text__new_version", [version_number])}<div class="new-version-description client-text-color-500">${version_description}</div>${this.getString("dialog_version_update__confirm_text__question_reload_page")}`,
            {ok_button: {text: this.getString("dialog_version_update__button_reload")}, cancel_button: {text: this.getString("dialog_version_update__option_not_now")}}
        ).done((result) => {
            if (result) {
                window.location.reload(true);
            }
        });
    },

    Settings: Backbone.ModelWithStorage.extend({

        defaults: () => {
            return {
                max_connection_retries: -1,
                idling: true,
                idling_time: 'default',
                notifications: true,
                notifications_private: true,
                notifications_group: true,
                jingle_calls: true,
                notifications_volume_enabled: true,
                notifications_volume: 0.50,
                message_preview_private: false,
                message_preview_group: false,
                private_sound: true,
                group_sound: true,
                background: {type: 'default'},
                side_panel: {theme: 'dark', blur: false, transparency: 50},
                appearance: {blur: 0, vignetting: 0, color: '#E0E0E0'},
                main_color: 'default',
                emoji_font: 'default',
                font_size: 'normal',
                sound_on_private_message: 'beep_up',
                sound_on_group_message: 'beep_up',
                call_attention: true,
                load_media: 'default',
                typing_notifications: 'default',
                mapping_service: 'default',
                desktop_autostart: false,
                reconnection_logs: false,
                debug_mode: false,
                sound_on_call: 'marching-band-dave-girtsman',
                sound_on_dialtone: 'marching-band-dave-girtsman',
                sound_on_connection: '_call_connecting',
                sound_on_attention: 'attention',
                sound_on_auth_request: '_auth_request',
                sound_on_call_busy: '_phone_busy',
                hotkeys: 'enter',
                avatar_shape: 'circle',
                device_metadata: 'default',
                language: 'default',
                load_history: true,
                mam_requests_limit: 200,
                mam_messages_limit_start: 1,
                mam_messages_limit: 20,
            }
        },
    }),

    start: function () {
        this.check_config.done((result) => {
            this.cacheFavicons();
            this.check_config = undefined;
            result && this.trigger('start');
        });
    },

    configure: function (config) {
        this.loadTranslations(this.get('default_language')).then((language) => {
            this.default_translation = language.translation ;
            return this.loadTranslations();}).then((language) => {
                this.setLocale(language.lang, language.translation);
            _.extend(constants, _.pick(config, [
                'CONNECTION_URL',
                'PERSONAL_AREA_URL',
                'LOG_LEVEL',
                'SYNCHRONIZATION_RSM_MAX',
                'ASSETS_URL_PREFIX',
                'CONTAINER_ELEMENT',
                'XABBER_ACCOUNT_URL',
                'REGISTER_XMPP_ACCOUNT',
                'REGISTER_XMPP_ACCOUNT_URL',
                'REGISTER_XMPP_ACCOUNT_TEXT',
                'USE_SOCIAL_AUTH',
                'USE_TAB_SIGNALS',
                'CLIENT_RESOURCE',
                'CONTAINER',
                'CHECK_VERSION',
                'DESKTOP_AUTOSTART_OPTION',
                'DEFAULT_LOGIN_SCREEN',
                'STORAGE_NAME_ENDING',
                'CLIENT_NAME',
                'SHORT_CLIENT_NAME',
                'CLIENT_LOGO',
                'TOOLBAR_LOGO',
                'ENABLE_XABBER_ACCOUNT',
                'SCREEN_ABOUT',
                'DISABLE_LOOKUP_WS',
                'PRIVACY_LOAD_MEDIA',
                'PRIVACY_TYPING_NOTIFICATIONS',
                'PRIVACY_MAPPING_SERVICE',
            ]));

            let log_level = constants['LOG_LEVEL_'+constants.LOG_LEVEL];
            constants.LOG_LEVEL = log_level || constants.LOG_LEVEL_ERROR;
            Strophe.setLogLevel(constants.LOG_LEVEL);
            constants.MATERIAL_COLORS.includes(config.MAIN_COLOR) && (constants.MAIN_COLOR = config.MAIN_COLOR);
            (this._settings.get("main_color") === 'default') && this._settings.set("main_color", constants.MAIN_COLOR);
            this.trigger("update_main_color");
            if (this._settings.get("load_media") === 'default' && config.PRIVACY_LOAD_MEDIA != null)
                this._settings.set("load_media", config.PRIVACY_LOAD_MEDIA);
            else if (this._settings.get("load_media") === 'default')
                this._settings.set("load_media", true);
            if (this._settings.get("typing_notifications") === 'default' && config.PRIVACY_TYPING_NOTIFICATIONS != null)
                this._settings.set("typing_notifications", config.PRIVACY_TYPING_NOTIFICATIONS);
            else if (this._settings.get("typing_notifications") === 'default')
                this._settings.set("typing_notifications", true);
            if (this._settings.get("device_metadata") === 'default' && config.PRIVACY_DEVICE_METADATA_DEFAULT != null)
                this._settings.set("device_metadata", config.PRIVACY_DEVICE_METADATA_DEFAULT);
            else if (this._settings.get("device_metadata") === 'default')
                this._settings.set("device_metadata", 'contacts');
            if (this._settings.get("mapping_service") === 'default' && config.PRIVACY_MAPPING_SERVICE != null)
                this._settings.set("mapping_service", config.PRIVACY_MAPPING_SERVICE);
            else if (this._settings.get("mapping_service") === 'default')
                this._settings.set("mapping_service", true);
            if (this._settings.get("idling_time") === 'default' && config.IDLING_DEFAULT_TIMEOUT != null)
                this._settings.set("idling_time", config.IDLING_DEFAULT_TIMEOUT);
            else if (this._settings.get("idling_time") === 'default')
                this._settings.set("idling_time", constants.IDLING_DEFAULT_TIMEOUT);

            window.xabber = this;
            _.defaults(window, env);
            if (config.SYNCHRONIZATION_RSM_MAX)
                constants.SYNCHRONIZATION_RSM_MAX = config.SYNCHRONIZATION_RSM_MAX;
            if (config.ASSETS_URL_PREFIX) {
                constants.ASSETS_URL_PREFIX = config.ASSETS_URL_PREFIX;
            }
            if (config.XABBER_SERVICE_URL)
                constants.XABBER_SERVICE_URL = config.XABBER_SERVICE_URL;
            if (config.XABBER_SERVICE_IFRAME_URL)
                constants.XABBER_SERVICE_IFRAME_URL = config.XABBER_SERVICE_IFRAME_URL;
            if (config.BACKGROUND_IMAGES_XML_URL)
                constants.BACKGROUND_IMAGES_XML_URL = config.BACKGROUND_IMAGES_XML_URL;
            if (config.BACKGROUND_PATTERNS_XML_URL)
                constants.BACKGROUND_PATTERNS_XML_URL = config.BACKGROUND_PATTERNS_XML_URL;
            if (config.CONTAINER_ELEMENT)
                constants.CONTAINER_ELEMENT = config.CONTAINER_ELEMENT;
            if (config.REGISTRATION_DOMAINS)
                constants.REGISTRATION_DOMAINS = config.REGISTRATION_DOMAINS;
            if (config.LOGIN_DOMAINS)
                constants.LOGIN_DOMAINS = config.LOGIN_DOMAINS;
            if (config.TRUSTED_DOMAINS)
                constants.TRUSTED_DOMAINS = config.TRUSTED_DOMAINS;
            if (config.RECOMMENDED_DOMAIN)
                constants.RECOMMENDED_DOMAIN = config.RECOMMENDED_DOMAIN;
            if (config.DOWNTIME_RECONNECTION_TIMEOUT)
                constants.DOWNTIME_RECONNECTION_TIMEOUT = config.DOWNTIME_RECONNECTION_TIMEOUT;
            if (config.IDLING_MINIMAL_TIMEOUT)
                constants.IDLING_MINIMAL_TIMEOUT = config.IDLING_MINIMAL_TIMEOUT;
            if (config.IDLING_MAXIMUM_TIMEOUT)
                constants.IDLING_MAXIMUM_TIMEOUT = config.IDLING_MAXIMUM_TIMEOUT;
            if (config.PING_SENDING_INTERVAL)
                constants.PING_SENDING_INTERVAL = config.PING_SENDING_INTERVAL;
            if (config.REGISTRATION_BUTTON != null)
                constants.REGISTRATION_BUTTON = config.REGISTRATION_BUTTON;
            if (config.REGISTRATION_CUSTOM_DOMAIN != null)
                constants.REGISTRATION_CUSTOM_DOMAIN = config.REGISTRATION_CUSTOM_DOMAIN;
            if (config.LOGIN_CUSTOM_DOMAIN != null)
                constants.LOGIN_CUSTOM_DOMAIN = config.LOGIN_CUSTOM_DOMAIN;
            if (config.SHORT_CLIENT_DESCRIPTION)
                constants.SHORT_CLIENT_DESCRIPTION = config.SHORT_CLIENT_DESCRIPTION;
            if (config.DEFAULT_EMOJI_FONT)
                constants.DEFAULT_EMOJI_FONT = config.DEFAULT_EMOJI_FONT;
            if (config.EMOJI_FONTS_LIST && _.isObject(config.EMOJI_FONTS_LIST))
                constants.EMOJI_FONTS_LIST = config.EMOJI_FONTS_LIST;
            else {
                Object.keys(constants.EMOJI_FONTS_LIST).forEach((item_key) => {
                    let item = constants.EMOJI_FONTS_LIST[item_key];
                    if (item.is_outside_url)
                        return;
                    item.url = constants.ASSETS_URL_PREFIX + item.url;
                });
            }
            (this._settings.get("emoji_font") === 'default') && this._settings.set("emoji_font", constants.DEFAULT_EMOJI_FONT);

            if (config.CLIENT_NAME && !config.SHORT_CLIENT_NAME)
                constants.SHORT_CLIENT_NAME = config.CLIENT_NAME;
            else if (!config.CLIENT_NAME && config.SHORT_CLIENT_NAME)
                constants.CLIENT_NAME = config.SHORT_CLIENT_NAME;

            if (config.TURN_SERVERS_LIST) {
                if (_.isArray(config.TURN_SERVERS_LIST))
                    _.extend(constants, {TURN_SERVERS_LIST: config.TURN_SERVERS_LIST});
                else if (_.isObject(config.TURN_SERVERS_LIST) && Object.keys(config.TURN_SERVERS_LIST).length)
                    _.extend(constants, {TURN_SERVERS_LIST: [config.TURN_SERVERS_LIST]});
            }
            if (config.FONT_SIZES_LIST) {
                if (_.isArray(config.FONT_SIZES_LIST))
                    _.extend(constants, {FONT_SIZES_LIST: config.FONT_SIZES_LIST});
            }

            constants.LOADING_PLACEHOLDER = constants.ASSETS_URL_PREFIX + constants.LOADING_PLACEHOLDER;
            constants.FAVICON_DEFAULT = constants.ASSETS_URL_PREFIX + constants.FAVICON_DEFAULT;
            constants.FAVICON_DEFAULT_GREY = constants.ASSETS_URL_PREFIX + constants.FAVICON_DEFAULT_GREY;
            constants.FAVICON_MESSAGE = constants.ASSETS_URL_PREFIX + constants.FAVICON_MESSAGE;
            constants.BACKGROUND_IMAGE = constants.ASSETS_URL_PREFIX + constants.BACKGROUND_IMAGE;


            constants.CLIENT_LOGO = constants.ASSETS_URL_PREFIX + constants.CLIENT_LOGO;
            constants.TOOLBAR_LOGO = constants.ASSETS_URL_PREFIX + constants.TOOLBAR_LOGO;

            if (!constants.CONNECTION_URL) {
                utils.dialogs.error(this.getString("client_error__missing_connection_url"));
                this.check_config.resolve(false);
                return;
            }
            let broadcast_dfd = new $.Deferred();
            broadcast_dfd.done(() => {
                if (bc && bc.disabled_client){
                    utils.dialogs.error(this.getString("client_error__another_tab_active"));
                    this.check_config.resolve(false);
                    return;
                }

                let self = this;
                if (!Backbone.useLocalStorage && !this.cache.ignore_localstorage_warning) {
                    utils.dialogs.warning(this.getString("client_warning__no_local_storage"),
                        [{name: this.getString("ignore"), text: this.getString("client_error__option_show_msg_again")}]
                    ).done(function (res) {
                        res && res.ignore && self._cache.save('ignore_localstorage_warning', true);
                    });
                }

                this.requestNotifications().done(function (granted) {
                    let emoji_dfd = new $.Deferred();
                    emoji_dfd.done(() => {
                        self._cache.save('notifications', granted);
                        self._cache.save('endpoint_key', undefined);
                        self.check_config.resolve(true);
                    });
                    if (self._settings.get("emoji_font") === 'system' || !Object.keys(constants.EMOJI_FONTS_LIST).length)
                        emoji_dfd.resolve();
                    else {
                        let emoji_obj = constants.EMOJI_FONTS_LIST[self._settings.get("emoji_font")],
                            emoji_url;
                        if (emoji_obj && emoji_obj.url) {
                            emoji_url = emoji_obj.url;
                            self.loadEmojiFont(emoji_url, emoji_dfd);
                        }
                        else {
                            emoji_dfd.resolve();
                        }
                    }
                });
            });
            let bc;
            if (constants.USE_TAB_SIGNALS){
                try {
                    bc = new BroadcastChannel("xabber-web");
                } catch (e) {
                    console.error(e);
                }
                if (bc){
                    let bc_message_timeout = setTimeout(() => {
                        broadcast_dfd.resolve();
                    }, 1000);
                    bc.onmessage = (event) => {
                        if (event.data === `1` && !bc.disabled_client) {
                            bc.postMessage(`2`);
                        }
                        if (event.data === `2`) {
                            bc.disabled_client = true;
                            clearTimeout(bc_message_timeout);
                            broadcast_dfd.resolve();
                        }
                    };

                    bc.postMessage(`1`);
                }
            } else {
                broadcast_dfd.resolve();
            }
        });
    },

    fetchURLParams: function () {
        let splitted_url = window.location.href.split(/[?#]/),
            splitted_url_anchor = window.location.href.split('#');
        this.url_params = {};
        if (splitted_url.length > 1) {
            let idx, param, params = splitted_url[1].split('&');
            for (idx = 0; idx < params.length; idx++) {
                param = params[idx].split('=');
                if (param.length === 1) {
                    this.url_params[param[0]] = null;
                } else {
                    this.url_params[param[0]] = param[1];
                }
            }
        }
        if (splitted_url_anchor.length > 1) {
            this.url_params['anchor'] = splitted_url[1];
        }
        window.history.pushState(null, null, window.location.pathname);
    },

    getStorageName: function () {
        let name = constants.STORAGE_NAME + '-' + constants.STORAGE_VERSION;
        if (constants.STORAGE_NAME_ENDING) {
            name = name + '-' + constants.STORAGE_NAME_ENDING;
        }
        return name;
    },

    cleanUpStorage: function () {
        let full_storage_name = constants.STORAGE_NAME + '-' + constants.STORAGE_VERSION;
        for (let key in window.localStorage) {
            if (key.startsWith('xabber') &&
                    !key.startsWith(full_storage_name)) {
                window.localStorage.removeItem(key);
            }
        }
    },

    requestNotifications: function () {
        let result = new $.Deferred(),
            self = this;
        if (!window.Notification) {
            result.resolve(null);
        } else if (window.Notification.permission === 'granted') {
            result.resolve(true);
        } else {
            if (!self.cache.ignore_notifications_warning)
                self.notifications_placeholder = new self.NotificationsPlaceholder();
            result.resolve(false);
        }
        return result.promise();
    },

    playPausePlyr: function () {
        if (!this.current_plyr_player)
            return;
        if (this.current_plyr_player.$audio_elem){
            if (!this.current_plyr_player.$audio_elem.voice_message){
                let msg = this.current_plyr_player.chat_item.model.messages.get(this.current_plyr_player.$audio_elem.closest('.chat-message').data('uniqueid')),
                    uri = this.current_plyr_player.$audio_elem.closest('.link-file').find('.file-link-download').attr('href'),
                    file = (msg.get('files') || []).find(f => f.sources[0] === uri),
                    peaks = file && file.peaks ? file.peaks : null;

                let f_url = $(this.current_plyr_player.$audio_elem).find('.file-link-download').attr('href');
                $(this.current_plyr_player.$audio_elem).find('.mdi-play').removeClass('no-uploaded');
                this.current_plyr_player.$audio_elem.voice_message = this.current_plyr_player.chat_item.content.renderVoiceMessage($(this.current_plyr_player.$audio_elem).find('.file-container')[0], f_url, null, peaks);
            } else {
                this.current_plyr_player.$audio_elem.voice_message.playPause()
            }
        } else
            this.current_plyr_player.togglePlay();
        this.trigger('plyr_player_updated');
    },

    stopPlyr: function () {
        if (!this.current_plyr_player && this.plyr_player_popup)
            return;
        this.plyr_players.forEach((item) => {
            if (item.$audio_elem){
                if (item.$audio_elem.voice_message)
                    item.$audio_elem.voice_message.stopTime();
            }
        });
        if (this.plyr_player_popup)
            this.plyr_player_popup.closePopup();
        else {
            this.current_plyr_player = null;
            this.trigger('plyr_player_updated');
        }
    },

    popupPlyr: function (ev) {
        let $item = $(ev.target);
        if ($item.closest('.chat-tool-plyr-controls').length){
            return;
        }
        if (this.current_plyr_player.$audio_elem){
            if (!(this.current_plyr_player && this.current_plyr_player.chat_item && this.current_plyr_player.message_unique_id))
                return;
            let chat = this.current_plyr_player.chat_item.model;
            this.chats_view.openChat(chat.item_view, {right_contact_save: true, clear_search: false});
            this.body.setScreen(this.body.screen.get('name'), {right: 'message_context', model: chat });
            if (this.body.screen.get('right_contact') && this.body.screen.get('right') === 'message_context') {
                chat.contact.showDetailsRight('all-chats', {right_saved: false});
            }
            chat.getMessageContext(this.current_plyr_player.message_unique_id, {message: true});

        } else {
            if (this.plyr_player_popup)
                this.plyr_player_popup.minimizePopup();
        }
    },

    nextPlyr: function () {
        let player_index = this.current_plyr_player.chat_item.model.plyr_players.indexOf(this.current_plyr_player);
        if (player_index === -1 && this.current_plyr_player.player_item)
            player_index = this.current_plyr_player.chat_item.model.plyr_players.indexOf(this.current_plyr_player.player_item);
        if (!this.current_plyr_player || !(player_index >= 0 && player_index < this.current_plyr_player.chat_item.model.plyr_players.length - 1))
            return;
        if (this.current_plyr_player.chat_item.model.plyr_players[player_index + 1].$audio_elem){
            let next_item = this.current_plyr_player.chat_item.model.plyr_players[player_index + 1];
            if (!next_item.$audio_elem.voice_message){
                let msg = this.current_plyr_player.chat_item.model.messages.get($(next_item.$audio_elem).closest('.chat-message').data('uniqueid')),
                    uri = $(next_item.$audio_elem).closest('.link-file').find('.file-link-download').attr('href'),
                    file = (msg.get('files') || []).find(f => f.sources[0] === uri),
                    peaks = file && file.peaks ? file.peaks : null;

                let f_url = $(next_item.$audio_elem).find('.file-link-download').attr('href');
                $(next_item.$audio_elem).find('.mdi-play').removeClass('no-uploaded');
                next_item.$audio_elem.voice_message = this.current_plyr_player.chat_item.content.renderVoiceMessage($(next_item.$audio_elem).find('.file-container')[0], f_url, this.current_plyr_player.chat_item.model, peaks);
            } else {
                next_item.$audio_elem.voice_message.play()
            }
        } else{
            if (!this.plyr_player_popup){
                this.plyr_player_popup = new this.PlyrPlayerPopupView({});
                this.plyr_player_popup.show({player: this.current_plyr_player.chat_item.model.plyr_players[player_index + 1]});
            } else
                this.plyr_player_popup.showNewVideo({player: this.current_plyr_player.chat_item.model.plyr_players[player_index + 1]});
        }
        setTimeout(() => {
            this.trigger('plyr_player_updated');
        }, 500);
    },

    previousPlyr: function () {
        let player_index = this.current_plyr_player.chat_item.model.plyr_players.indexOf(this.current_plyr_player);
        if (player_index === -1 && this.current_plyr_player.player_item)
            player_index = this.current_plyr_player.chat_item.model.plyr_players.indexOf(this.current_plyr_player.player_item);
        if (!this.current_plyr_player || !(player_index <= this.current_plyr_player.chat_item.model.plyr_players.length && player_index > 0))
            return;
        if (this.current_plyr_player.chat_item.model.plyr_players[player_index - 1].$audio_elem){
            let prev_item = this.current_plyr_player.chat_item.model.plyr_players[player_index - 1];
            if (!prev_item.$audio_elem.voice_message){
                let msg = this.current_plyr_player.chat_item.model.messages.get($(prev_item.$audio_elem).closest('.chat-message').data('uniqueid')),
                    uri = $(prev_item.$audio_elem).closest('.link-file').find('.file-link-download').attr('href'),
                    file = (msg.get('files') || []).find(f => f.sources[0] === uri),
                    peaks = file && file.peaks ? file.peaks : null;
                let f_url = $(prev_item.$audio_elem).find('.file-link-download').attr('href');
                $(prev_item.$audio_elem).find('.mdi-play').removeClass('no-uploaded');
                prev_item.$audio_elem.voice_message = this.current_plyr_player.chat_item.content.renderVoiceMessage($(prev_item.$audio_elem).find('.file-container')[0], f_url, this.current_plyr_player.chat_item.model, peaks);
            } else {
                prev_item.$audio_elem.voice_message.play()
            }
        } else{
            if (!this.plyr_player_popup){
                this.plyr_player_popup = new this.PlyrPlayerPopupView({});
                this.plyr_player_popup.show({player: this.current_plyr_player.chat_item.model.plyr_players[player_index - 1]});
            } else
                this.plyr_player_popup.showNewVideo({player: this.current_plyr_player.chat_item.model.plyr_players[player_index - 1]});
        }
        setTimeout(() => {
            this.trigger('plyr_player_updated');
        }, 500);
    },

    updatePlyrControls: function (self) {
        self.$('.chat-tool-player').showIf(this.current_plyr_player);
        self.$el.switchClass('chat-head-player-enabled', this.current_plyr_player);
        if (this.current_plyr_player && this.current_plyr_player.$audio_elem) {
            if (this.current_plyr_player.$audio_elem.voice_message){
                let voice_message = this.current_plyr_player.$audio_elem.voice_message;
                self.$('.chat-head-player-type').text(this.getString("chat_message_voice"));
                self.$('.btn-play-pause-plyr .mdi-play').hideIf(voice_message.isPlaying());
                self.$('.btn-play-pause-plyr .mdi-pause').hideIf(!voice_message.isPlaying());
                self.$('.btn-play-pause-plyr').switchClass('active-plyr', voice_message.isPlaying());
                self.$('.btn-previous-plyr').switchClass('before-active-plyr', voice_message.isPlaying());
                let player_index = this.current_plyr_player.chat_item.model.plyr_players.indexOf(this.current_plyr_player);
                self.$('.btn-next-plyr').switchClass('disabled', !(player_index >= 0 && player_index < this.current_plyr_player.chat_item.model.plyr_players.length - 1));
                self.$('.btn-previous-plyr').switchClass('disabled', !(player_index <= this.current_plyr_player.chat_item.model.plyr_players.length && player_index > 0));
                self.$('.mdi-player-type-icon').addClass('hidden');
                self.$('.player-poster').addClass('hidden');
                self.$('.voice-message-player-avatar').removeClass('hidden');
                self.$('.voice-message-player-avatar').setAvatar(this.current_plyr_player.contact_avatar, 32, this.current_plyr_player.chat_item && this.current_plyr_player.chat_item.account);
                self.updatePlyrTitle();
                let duration = Math.round(voice_message.getDuration());
                self.$('.chat-head-player-total-time').text(utils.pretty_duration(duration));
                let timerId = setInterval(function() {
                    let cur_time = Math.round(voice_message.getCurrentTime());
                    if (voice_message.isPlaying())
                        self.$('.chat-head-player-current-time').text(utils.pretty_duration(cur_time));
                    else
                        clearInterval(timerId);
                }, 100);
                (this.plyr_player_popup) && this.plyr_player_popup.$el.addClass('hidden2');
                (this.plyr_player_popup) && this.plyr_player_popup.$el.closest('#modals').siblings('#' + this.plyr_player_popup.$el.data('overlayId')).addClass('hidden2');
            }
        }
        else if (this.current_plyr_player) {
            self.$('.chat-head-player-current-time').text(utils.pretty_duration(isNaN(this.current_plyr_player.currentTime) ? 0 : parseInt(this.current_plyr_player.currentTime)));
            self.$('.chat-head-player-total-time').text(utils.pretty_duration(parseInt(this.current_plyr_player.duration)));
            self.updatePlyrTitle();
            let poster = this.current_plyr_player.poster;
            if (poster){
                self.$('.mdi-player-type-icon').addClass('hidden');
                self.$('.player-poster').removeClass('hidden');
                self.$('.player-poster').attr("src", poster);
            } else {
                self.$('.mdi-player-type-icon').removeClass('hidden');
                self.$('.player-poster').addClass('hidden');
            }
            self.$('.voice-message-player-avatar').addClass('hidden');
            if (this.current_plyr_player.provider !== 'html5')
                self.$('.chat-head-player-type').text(this.current_plyr_player.provider);
            else
                self.$('.chat-head-player-type').text(this.getString("chat_message_video"));
            self.$('.btn-play-pause-plyr .mdi-play').hideIf(this.current_plyr_player.playing);
            self.$('.btn-play-pause-plyr .mdi-pause').hideIf(!this.current_plyr_player.playing);
            self.$('.btn-play-pause-plyr').switchClass('active-plyr', this.current_plyr_player.playing);
            self.$('.btn-previous-plyr').switchClass('before-active-plyr', this.current_plyr_player.playing);
            let player_index = this.current_plyr_player.chat_item.model.plyr_players.indexOf(this.current_plyr_player.player_item);
            self.$('.btn-next-plyr').switchClass('disabled', !(player_index >= 0 && player_index < this.current_plyr_player.chat_item.model.plyr_players.length - 1));
            self.$('.btn-previous-plyr').switchClass('disabled', !(player_index <= this.current_plyr_player.chat_item.model.plyr_players.length && player_index > 0));
            (this.plyr_player_popup) && this.plyr_player_popup.$el.removeClass('hidden2');
            (this.plyr_player_popup) && this.plyr_player_popup.$el.closest('#modals').siblings('#' + this.plyr_player_popup.$el.data('overlayId')).removeClass('hidden2');
        }
    },

    updatePlyrTitle: function (self) {
        if (!this.current_plyr_player)
            return;
        let $title_elem = self.$('.chat-head-player-title .chat-head-player-title-text'),
            title;
        if (this.current_plyr_player && this.current_plyr_player.$audio_elem)
            title = this.current_plyr_player.author;
        else if (this.current_plyr_player)
            title = this.current_plyr_player.config.title ?
                this.current_plyr_player.config.title :
                this.current_plyr_player.provider === 'html5' ?
                    this.current_plyr_player.source.substring(this.current_plyr_player.source.lastIndexOf('/')+1)
                    : this.getString("chat_message_video");
        $title_elem.text(title);
        if (self.$('.chat-head-player-title')[0] && utils.isOverflownWidth(self.$('.chat-head-player-title')[0])){
            $title_elem.addClass('active-animation-player-title');
            $title_elem.text(title + ' ⚫︎︎ ⚫︎︎ ⚫︎︎ ' + title);
            let text = $title_elem[0],
                containerWidth = self.$('.chat-head-player-title')[0].offsetWidth,
                textWidth = text.offsetWidth;
            text.style.animationDuration = `${textWidth / containerWidth * 10}s`;
        } else
            $title_elem.removeClass('active-animation-player-title');

    },

    updatePlyrTime: function (self) {
        if (this.current_plyr_player){
            if (this.current_plyr_player && this.current_plyr_player.$audio_elem) {
            }
            else if (!isNaN(this.current_plyr_player.currentTime))
                self.$('.chat-head-player-current-time').text(utils.pretty_duration(isNaN(this.current_plyr_player.currentTime) ? 0 : parseInt(this.current_plyr_player.currentTime)));
        }
    },

    updateFaviconConnected: function () {
        let is_disconnected = false;
        this.accounts.each((account) => {
            if (account.get('enabled') && (!account.isConnected() || (account.session && account.session.get('auth_failed')))){
                is_disconnected = true;

            }
        });
        this.updateAllMessageCounterOnDisconnect(is_disconnected);
    },

    disconnectWhenConnecting: function () {
        this.accounts.each((account) => {
            if (account.session && account.connection && account.get('enabled') && !account.session.get('reconnecting') && !account.session.get('connected')){
                account.activate();
            }
        });
    },

    extendWith: function () {
        return _.reduce(arguments, function (instance, module) {
            return instance;
        }, this);
    }
});

export default new Xabber();
